	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                             
	"REMARK" NVARCHAR2(600),                                                                                                                                                                                        
	"ISSUE_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                        
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                             
	"EXT_USER_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                     
	"IS_SEND_DING_NOTIFY" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                         
	"DING_NOTIFY_TASK_ID" NVARCHAR2(32),                                                                                                                                                                            
	"IS_SEND_MSG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                                 
	"STATUS" NVARCHAR2(32) DEFAULT 'WAIT' NOT NULL ENABLE,                                                                                                                                                          
	"IS_END" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                                      
	"REPORT_TIME" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                             
	"OPERATING_TIME" DATE,                                                                                                                                                                                          
	"REASON" NVARCHAR2(1024),                                                                                                                                                                                       
	"END_TIME" DATE,                                                                                                                                                                                                
	"SUMMARY" CLOB,                                                                                                                                                                                                 
	"SYNC_USER_ID" NVARCHAR2(50),                                                                                                                                                                                   
