	"EXT_ORG_ID" NUMBER(20,0),                                                                                                                                                                                      
	"SOURCE_ASSISTANCE" NVARCHAR2(50),                                                                                                                                                                              
	"TRANSFER_EXT_USER_ID" NUMBER(20,0),                                                                                                                                                                            
	 PRIMARY KEY ("ISSUE_USER_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                            
   ) ;                                                                                                                                                                                                           

